// Crops the P7 /types-of-personal-goals photos (Gemini P7-1 to P7-7, generated by Grant 2026-11-05) to their slots (2x) and writes one
// combined script that places them in Figma frame 116:4994 (v2.3.3, desktop) and its mobile frames. Reuses the place()/tag() helpers
// from place-p4-photos.js. The media placeholders are hidden, not deleted.
// Usage: node docs/brand/assets/site-imagery/place-p7-photos.js  →  out/p7-<slot>-{desktop,mobile}.jpg, out/p7-crops-sheet.jpg,
// and place-p7.js in the OS temp folder (run it in Figma: Chrome javascript_tool paste route, see notes/figma-pillar-v2/README.md).
// Face checks are in the crops: hero starts below the beard line; 4.3 cuts the cheek at the left; 4.5 starts below the writer's
// cheek and ends above the book spines (real titles); card 3 starts below the in-focus faces at the table.
const fs = require('fs');
const os = require('os');
const path = require('path');
const { createCanvas, loadImage } = require('../facebook/node_modules/@napi-rs/canvas');
const dir = __dirname;
const p4 = fs.readFileSync(path.join(dir, 'place-p4-photos.js'), 'utf8');
const header = p4.slice(p4.indexOf('const header = `') + 16, p4.indexOf('\n`;\n(async'));
const G = id => `Gemini_Generated_Image_${id}.jpg`;
const SLOTS = [
  { key: 'hero', src: G('vwuqhgvwuqhgvwuq'), d: { node: '116:5015', w: 460, h: 400, crop: [300, 360, 1647, 1432] }, m: { node: '116:5602', w: 335, h: 230, crop: [300, 600, 1736, 1192] },
    tag: ['Lead area · Money', 'Move $100 to savings every Friday.'], corner: 'tr' },
  { key: 'p41', src: G('405h5r405h5r405h'), d: { node: '116:5241', w: 360, h: 320, crop: [192, 0, 2016, 1792] }, m: { node: '116:5791', w: 335, h: 210, crop: [0, 288, 2400, 1504] } },
  { key: 'p43', src: G('cxr6zncxr6zncxr6'), d: { node: '116:5279', w: 360, h: 300, crop: [400, 125, 2000, 1667] }, m: { node: '116:5846', w: 335, h: 210, crop: [400, 400, 2000, 1254] } },
  { key: 'p45', src: G('wnil12wnil12wnil'), d: { node: '116:5377', w: 360, h: 320, crop: [800, 350, 990, 880] }, m: { node: '116:5903', w: 335, h: 210, crop: [720, 500, 1117, 700] } },
  { key: 'p410a', src: G('y7vk3oy7vk3oy7vk'), d: { node: '116:5502', w: 286, h: 180, crop: [150, 0, 2441, 1536] }, m: { node: '116:6045', w: 260, h: 150, crop: [45, 0, 2662, 1536] } },
  { key: 'p410b', src: G('s8iunes8iunes8iu'), d: { node: '116:5509', w: 286, h: 180, crop: [155, 0, 2441, 1536] }, m: { node: '116:6052', w: 260, h: 150, crop: [45, 0, 2662, 1536] } },
  { key: 'p410c', src: G('fzdo2nfzdo2nfzdo'), d: { node: '116:5516', w: 286, h: 180, crop: [840, 830, 1122, 706] }, m: { node: '116:6059', w: 260, h: 150, crop: [790, 830, 1224, 706] } },
];
async function crop(file, [x, y, w, h], ow, oh, out) {
  const img = await loadImage(path.join(dir, 'source', file));
  const c = createCanvas(ow * 2, oh * 2); c.getContext('2d').drawImage(img, x, y, w, h, 0, 0, ow * 2, oh * 2);
  const buf = c.toBuffer('image/jpeg', 84); fs.writeFileSync(out, buf); return buf.toString('base64');
}
(async () => {
  fs.mkdirSync(path.join(dir, 'out'), { recursive: true });
  let js = header;
  const sheet = createCanvas(1500, 300 * SLOTS.length); const g = sheet.getContext('2d'); g.fillStyle = '#fff'; g.fillRect(0, 0, 1500, 300 * SLOTS.length);
  for (const [i, s] of SLOTS.entries()) {
    const dOut = path.join(dir, 'out', `p7-${s.key}-desktop.jpg`), mOut = path.join(dir, 'out', `p7-${s.key}-mobile.jpg`);
    const d64 = await crop(s.src, s.d.crop, s.d.w, s.d.h, dOut);
    const m64 = await crop(s.src, s.m.crop, s.m.w, s.m.h, mOut);
    js += `out.${s.key}_d = await place('${s.d.node}', '${d64}', ${s.d.w}, ${s.d.h}, 'Photo · ${s.key} · desktop', ${JSON.stringify(s.tag || null)}, '${s.corner || ''}', 1);\n`;
    js += `out.${s.key}_m = await place('${s.m.node}', '${m64}', ${s.m.w}, ${s.m.h}, 'Photo · ${s.key} · mobile', ${JSON.stringify(s.tag || null)}, '${s.corner || ''}', 0.85);\n`;
    const a = await loadImage(dOut), b = await loadImage(mOut); const k = 280 / Math.max(a.height, b.height);
    g.drawImage(a, 10, i * 300 + 10, a.width * k, a.height * k); g.drawImage(b, 30 + a.width * k, i * 300 + 10, b.width * k, b.height * k);
    g.fillStyle = '#000'; g.font = '20px sans-serif'; g.fillText(s.key, 1380, i * 300 + 40);
  }
  js += `figma.notify('P7 photos placed'); return out;\n})()`;
  new Function('figma', 'return ' + js.replace(/^\(async \(\) => \{/, '(async () => {'));
  fs.writeFileSync(path.join(os.tmpdir(), 'place-p7.js'), js);
  fs.writeFileSync(path.join(dir, 'out', 'p7-crops-sheet.jpg'), sheet.toBuffer('image/jpeg', 75));
  console.log('script', Math.round(js.length / 1024), 'KB →', path.join(os.tmpdir(), 'place-p7.js'));
})();
